sql_select += "from raw_coal_unloading r,colliery c where r.colliery=c.id;";
SQLExecute1('TZSqlServer', 1, sql_select, function(res) {
    if (res.errorCode === 0) {
        let alldata = res.data[0];
        let datas = [];
        alldata.forEach((obj) => {

            //查询当月的第一天和最后一天
            let spiltdate = obj.date.split("-");
            let enddate = `${spiltdate[0]}-${parseInt(spiltdate[1])+1}-01`;
            let startdate = `${spiltdate[0]}-${spiltdate[1]}-01`;

           // 统计当天和当月的数据
            let number_of_cars_day = 0,
                number_of_cars_month = 0;
                tonnage_day = 0,
                tonnage_month = 0;
            let daydata = alldata.filter(element => {
                return element.date === obj.date && element.colliery === obj.colliery && element.factory_name === obj.factory_name;
            });
            daydata.forEach(element => {
                number_of_cars_day = parseInt(number_of_cars_day) + parseInt(element.number_of_cars);
                tonnage_day = parseFloat(tonnage_day) + parseFloat(element.tonnage);
            });
            let monthdata = alldata.filter(element => {
                return element.date >= startdate && element.date < enddate && element.colliery === obj.colliery && element.factory_name === obj.factory_name;
            });
            monthdata.forEach(element => {
                number_of_cars_month = parseInt(number_of_cars_month) + parseInt(element.number_of_cars);
                tonnage_month = parseFloat(tonnage_month) + parseFloat(element.tonnage);
            });

            let tabledata = {
                id: obj.id,
                factory_name: obj.factory_name,
                date: obj.date,
                class: obj.class,
                colliery: obj.mine_name,
                number_of_cars_class: obj.number_of_cars,
                tonnage_class: obj.tonnage,
                collieryid: obj.colliery,
                number_of_cars_day:number_of_cars_day,
                tonnage_day:tonnage_day,
                number_of_cars_month:number_of_cars_month,
                tonnage_month:tonnage_month,
            };
            datas.push(tabledata);
        });
        $Variable.rawCoalUnloaddata = JSON.stringify(datas);
        let date = new Date().format("yyyy-MM-dd");
        let selectdata = datas.filter(obj => {
            return obj.date === date;
        });

        Table1.SetData(selectdata);
    } else {
        Infor("查询原煤卸车情况信息失败", "warning");
    }

});


